describe('verifyStripeSignature', () => {
  it('returns true for valid signature', async () => {
    const secret = 'whsec_testsecret';
    const rawBody = '{"id":"evt_test"}';
    const timestamp = Math.floor(Date.now() / 1000);
    const signedPayload = `${timestamp}.${rawBody}`;

    const expectedSignature = await testCryptoProvider.hmacSha256(secret, signedPayload);
    const header = `t=${timestamp},v1=${expectedSignature}`;

    const result = await verifyStripeSignature(rawBody, header, secret, { crypto: testCryptoProvider });
    expect(result).toBe(true);
  });

  it('returns false for invalid signature', async () => {
    const result = await verifyStripeSignature('{}', 't=123,v1=invalidsig', 'secret', { crypto: testCryptoProvider });
    expect(result).toBe(false);
  });

  it('returns false for missing timestamp or signature', async () => {
    expect(await verifyStripeSignature('{}', 'v1=abc', 'secret', { crypto: testCryptoProvider })).toBe(false);
    expect(await verifyStripeSignature('{}', 't=123', 'secret', { crypto: testCryptoProvider })).toBe(false);
  });

  it('returns false for signature older than 5 minutes', async () => {
    const oldTimestamp = Math.floor(Date.now() / 1000) - 400;
    const header = `t=${oldTimestamp},v1=abc`;
    expect(await verifyStripeSignature('{}', header, 'secret', { crypto: testCryptoProvider })).toBe(false);
