  it('throws when OpenAI content is invalid JSON', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url === 'https://api.openai.com/v1/chat/completions') {
        return jsonResponse({ choices: [{ message: { content: 'not json' } }] })
