import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      slackBotToken: 'xoxb-test-token',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as TwilioIncomingSmsPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.slackChannel).toBe('C01234567')
    expect(result.slackTimestamp).toBe('1234567890.123456')
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig

  beforeEach(() => {
    baseConfig = {
      slackBotToken: 'xoxb-test-token'
    }
  })

  it('routes to #sales when body matches pricing', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage' && req.method === 'POST'
        ? jsonResponse({ ok: true, channel: 'C01234567', ts: '1234567890.123456' })
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: TwilioIncomingSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'I need pricing for your product'
    }

    const result = await handle(payload, { ...baseConfig, fetch })

    expect(calls.length).toBe(1)
    expect(calls[0].json).toEqual({ channel: '#sales', text: 'I need pricing for your product' })
    expect(calls[0].headers.get('authorization')).toBe('Bearer xoxb-test-token')
    expect(result.slackChannel).toBe('C01234567')
  })

  it('routes to #sales when body matches quote', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage'
        ? jsonResponse({ ok: true, channel: 'C01234567', ts: '1234567890.123456' })
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: TwilioIncomingSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Can I get a quote?'
    }

    await handle(payload, { ...baseConfig, fetch })

    expect(calls[0].json).toEqual({ channel: '#sales', text: 'Can I get a quote?' })
  })

  it('routes to #sales when body matches demo', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage'
        ? jsonResponse({ ok: true, channel: 'C01234567', ts: '1234567890.123456' })
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: TwilioIncomingSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'I would like a demo please'
    }

    await handle(payload, { ...baseConfig, fetch })

    expect(calls[0].json).toEqual({ channel: '#sales', text: 'I would like a demo please' })
  })

  it('routes to #support when body does not match', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage'
        ? jsonResponse({ ok: true, channel: 'C01234567', ts: '1234567890.123456' })
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: TwilioIncomingSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Hello, how are you?'
    }

    await handle(payload, { ...baseConfig, fetch })

    expect(calls[0].json).toEqual({ channel: '#support', text: 'Hello, how are you?' })
  })

  it('uses the From field as sender info but channel is determined by regex', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage'
        ? jsonResponse({ ok: true, channel: 'C01234567', ts: '1234567890.123456' })
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: TwilioIncomingSmsPayload = {
      ...SOURCE_EXAMPLE,
      From: '+15551234567',
      Body: 'I need a quote'
    }

    await handle(payload, { ...baseConfig, fetch })

    expect(calls[0].json).toEqual({ channel: '#sales', text: 'I need a quote' })
  })

  it('throws when Body is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, Body: undefined as unknown as string }

    await expect(handle(payload as unknown as TwilioIncomingSmsPayload, { ...baseConfig, fetch }))
      .rejects.toThrow('Missing required field: Body')
  })

  it('throws when From is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { ...SOURCE_EXAMPLE, From: undefined as unknown as string }

    await expect(handle(payload as unknown as TwilioIncomingSmsPayload, { ...baseConfig, fetch }))
      .rejects.toThrow('Missing required field: From')
  })

  it('throws on non-2xx Slack response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'invalid_auth' }, 401))

    const payload: TwilioIncomingSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'I need a quote'
    }

    await expect(handle(payload, { ...baseConfig, fetch }))
      .rejects.toThrow('Slack API error: 401 Unauthorized at POST https://slack.com/api/chat.postMessage')

    expect(calls.length).toBe(1)
  })

  it('throws when Slack returns ok: false', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ ok: false, error: 'channel_not_found' }, 200))

    const payload: TwilioIncomingSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'I need a quote'
    }

    await expect(handle(payload, { ...baseConfig, fetch }))
      .rejects.toThrow('Slack API returned ok: false')
  })

  it('sends correct Content-Type header', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage'
        ? jsonResponse({ ok: true, channel: 'C01234567', ts: '1234567890.123456' })
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: TwilioIncomingSmsPayload = {
      ...SOURCE_EXAMPLE,
      Body: 'Test message'
    }

    await handle(payload, { ...baseConfig, fetch })

    expect(calls[0].headers.get('content-type')).toBe('application/json')
  })

  it('regex is case insensitive', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://slack.com/api/chat.postMessage'
        ? jsonResponse({ ok: true, channel: 'C01234567', ts: '1234567890.123456' })
        : jsonResponse({ error: 'not found' }, 404)
    )

    const testCases = ['PRICING', 'Quote', 'DeMo', 'PrIcInG']
    for (const body of testCases) {
      calls.length = 0
      const payload: TwilioIncomingSmsPayload = { ...SOURCE_EXAMPLE, Body: body }
      await handle(payload, { ...baseConfig, fetch })
      expect(calls[0].json).toEqual({ channel: '#sales', text: body })
    }
  })
})

